      { allowFail: true, cwd: opts.repo }) ?? "";
    for (const line of listing.split("\n")) {
      const m = line.match(/^\s+\d\d-\d\d\s+\d\d:\d\d\s+\(([0-9a-f]{7,40})\)\s+(.+)$/);
