	}

	raw := strings.TrimSpace(string(out))
	if raw == "" {
		return "", errors.New("no transcript found")
	}

	cachePath, err := a.cacheTranscriptPath(cwd, sessionID)
	if err != nil {
		return "", err
	}

	data := []byte(raw)
	// Use the CLI conversation_id (or, if absent, the cwd-derived key) as
