		return "", fmt.Errorf("failed to write cached transcript: %w", err)
	}
	return cachePath, nil
}"},{"rank":5,"score":25.6178,"file_path":"agents/entire-agent-kiro/internal/kiro/hooks.go","start_line":674,"end_line":704,"focus_line":698,"snippet_start_line":674,"snippet_end_line":704,"symbol_start_line":674,"symbol_end_line":704,"language":"Go","kind":"method","symbol_id":"local/external-agents:Go:agents/entire-agent-kiro/internal/kiro/hooks.go:method:Agent.resolveStopIdentity","symbol_name":"resolveStopIdentity","qualified_name":"Agent.resolveStopIdentity","signature":"func (a *Agent) resolveStopIdentity(cwd string, raw hookInputRaw) sessionIdentity","signals":["body","symbol-usage","complete-symbol"],"snippet":"func (a *Agent) resolveStopIdentity(cwd string, raw hookInputRaw) sessionIdentity {
