  summary: "summary",
  checkpoint_summary: "summary",
  user: "user",
  user_message: "user",
  prompt: "user",
  assistant: "assistant",
  assistant_message: "assistant",
  response: "assistant",
  tool: "tool",
  tool_use: "tool",
  tool_result: "tool",
  session_start: "lifecycle",
  session_end: "lifecycle",
  checkpoint_created: "lifecycle",
