      }
      continue;
    }

    const speaker = line.match(LEGACY_SPEAKER);
    if (speaker) {
      flushSection();
      events.push({
        kind: speaker[1].toLowerCase(),
        text: speaker[2].trim(),
        source: "legacy-text",
      });
