// Text lives in a different field depending on the event. Tolerant by
// design: an unrecognised carrier yields "" rather than throwing, and an
// event with no text is still a valid event.
function extractText(rec) {
  const direct = rec.text ?? rec.intent ?? rec.summary ?? rec.prompt ?? rec.content;
  const fromMessage = rec.message?.content ?? rec.message?.text ?? rec.message;
  return flattenContent(direct) || flattenContent(fromMessage) || "";
