  let parsed;
  try {
    parsed = parser(raw);
  } catch (err) {
    // A parser bug must degrade to "unreadable", never take down the check.
    return {
      format, events: [], unknownEvents: [`parser-error:${err.message}`],
      malformed: 1, truncated: true, schemaVersion: null,
      readable: false, complete: false,
    };
